123	// SpendLimitService (exportado)
124	// ---------------------------------------------------------------------------
125	
126	export const SpendLimitService = {
127	  // -------------------------------------------------------------------------
128	  // CRUD — teto de gasto
129	  // -------------------------------------------------------------------------
130	
131	  /**
132	   * Busca o teto de gasto mensal da empresa. Retorna null se não configurado.
133	   * scope NULL = empresa inteira (caso v1 single-store).
134	   */
135	  async getSpendLimit(companyId: string, scope: string | null = null): Promise<SpendLimit | null> {
136	    try {
137	      let query = supabase
138	        .from('company_spend_limits')
139	        .select('*')
140	        .eq('company_id', companyId)
141	        .eq('period', 'month');
142	
143	      if (scope === null) {
144	        query = query.is('scope', null);
145	      } else {
146	        query = query.eq('scope', scope);
147	      }
148	
149	      const { data, error } = await query.maybeSingle();
150	      if (error) {
151	        logError('spendLimit.getSpendLimit', error);
152	        return null;
153	      }
154	      return (data as SpendLimit) ?? null;
155	    } catch (err) {
156	      logError('spendLimit.getSpendLimit', err);
157	      return null;
158	    }
159	  },
160	
161	  /**
162	   * Cria ou atualiza o teto de gasto mensal da empresa (upsert idempotente).
163	   * Usa ON CONFLICT (company_id, period) WHERE scope IS NULL (índice parcial da migration).
164	   *
165	   * @returns SpendLimit atualizado ou null em caso de erro.
166	   */
167	  async upsertSpendLimit(
168	    companyId: string,
169	    params: {
170	      amount: number;
171	      alertThresholds?: number[];
172	      scope?: string | null;
173	      financialContactEmail?: string | null;
174	      financialContactPhone?: string | null;
175	    },
176	  ): Promise<SpendLimit | null> {
177	    try {
178	      const payload: Record<string, unknown> = {
179	        company_id: companyId,
180	        period: 'month',
181	        amount: params.amount,
182	        scope: params.scope ?? null,
183	      };
184	      if (params.alertThresholds !== undefined) {
185	        payload.alert_thresholds = params.alertThresholds;
186	      }
187	      if (params.financialContactEmail !== undefined) {
188	        payload.financial_contact_email = params.financialContactEmail;
189	      }
190	      if (params.financialContactPhone !== undefined) {
191	        payload.financial_contact_phone = params.financialContactPhone;
192	      }
193	
194	      const { data, error } = await supabase
195	        .from('company_spend_limits')
196	        .upsert(payload, { onConflict: 'company_id,period,scope' })
197	        .select()
198	        .single();
199	
200	      if (error) {
201	        logError('spendLimit.upsertSpendLimit', error);
202	        return null;
203	      }
204	      return data as SpendLimit;
205	    } catch (err) {
206	      logError('spendLimit.upsertSpendLimit', err);
207	      return null;
208	    }
209	  },
210	
211	  // -------------------------------------------------------------------------
212	  // CRUD — faturamento mensal
213	  // -------------------------------------------------------------------------
214	
215	  /**
216	   * Busca o faturamento declarado da empresa em um mês (year_month = DATE no dia 1).
217	   * Normaliza para o primeiro dia do mês automaticamente.
218	   *
219	   * @param yearMonth Date ou string YYYY-MM-DD (sempre normalizada para o dia 1).
220	   */
221	  async getMonthlyRevenue(
222	    companyId: string,
223	    yearMonth: Date | string,
224	  ): Promise<MonthlyRevenue | null> {
225	    try {
226	      const ym =
227	        typeof yearMonth === 'string'
228	          ? yearMonth.slice(0, 7) + '-01'
229	          : monthStart(yearMonth);
230	
231	      const { data, error } = await supabase
232	        .from('company_monthly_revenue')
233	        .select('*')
234	        .eq('company_id', companyId)
235	        .eq('year_month', ym)
236	        .maybeSingle();
237	
238	      if (error) {
239	        logError('spendLimit.getMonthlyRevenue', error);
240	        return null;
241	      }
242	      return (data as MonthlyRevenue) ?? null;
243	    } catch (err) {
244	      logError('spendLimit.getMonthlyRevenue', err);
245	      return null;
246	    }
247	  },
248	
249	  /**
250	   * Cria ou atualiza o faturamento declarado do mês (upsert idempotente).
251	   * Normaliza year_month para o primeiro dia do mês.
252	   *
253	   * @param yearMonth Date ou string YYYY-MM-DD.
254	   * @param amount    Faturamento bruto BRL (>= 0).
255	   */
256	  async upsertMonthlyRevenue(
257	    companyId: string,
258	    yearMonth: Date | string,
259	    amount: number,
260	  ): Promise<MonthlyRevenue | null> {
261	    try {
262	      const ym =
263	        typeof yearMonth === 'string'
264	          ? yearMonth.slice(0, 7) + '-01'
265	          : monthStart(yearMonth);
266	
267	      const { data, error } = await supabase
268	        .from('company_monthly_revenue')
269	        .upsert(
270	          { company_id: companyId, year_month: ym, amount },
271	          { onConflict: 'company_id,year_month' },
272	        )
273	        .select()
274	        .single();
275	
276	      if (error) {
277	        logError('spendLimit.upsertMonthlyRevenue', error);
278	        return null;
279	      }
280	      return data as MonthlyRevenue;
281	    } catch (err) {
282	      logError('spendLimit.upsertMonthlyRevenue', err);
283	      return null;
284	    }
285	  },
286	
287	  // -------------------------------------------------------------------------
288	  // Avaliação do alerta de teto (R12)
289	  // -------------------------------------------------------------------------
290	
291	  /**
292	   * Avalia se o gasto acumulado do mês corrente cruzou algum threshold do teto.
293	   * Insere alerta idempotente em `notifications` para o MAIOR threshold cruzado
294	   * ainda não alertado no período.
295	   *
296	   * Regras (spec Slice 3 — contrato de ALERTA):
297	   *  - Dispara apenas o MAIOR threshold cruzado não-alertado (ex.: cruzou 92% → alerta 90%, não 80%).
298	   *  - Threshold >100% usa chave 'OVER'.
299	   *  - Idempotência: verifica SELECT LIMIT 1 por link antes do INSERT.
300	   *  - NUNCA bloqueia contratação (exceções capturadas silenciosamente — best-effort).
301	   *  - NÃO chama dentro de RPC de saldo (Article 8).
302	   *
303	   * @param companyId   UUID da empresa (= auth.uid() da empresa = wallets.user_id).
304	   * @param now         Data de referência (default: Date.now()). Injetável para testes.
305	   */
306	  async evaluateSpendAlert(companyId: string, now: Date = new Date()): Promise<void> {
307	    try {
308	      // 1. Buscar o teto configurado (scope = empresa inteira, v1)
309	      const limit = await SpendLimitService.getSpendLimit(companyId, null);
310	      if (!limit || limit.amount <= 0) return; // Sem teto configurado → nada a fazer
311	
312	      // 2. Calcular gasto acumulado do período
313	      const spend = await computeAccumulatedSpend(companyId, now);
314	      if (!spend) return; // Erro de query → best-effort, não bloqueia
315	
316	      const { totalAmount } = spend;
317	      const percent = (totalAmount / limit.amount) * 100;
318	
319	      // 3. Determinar o maior threshold cruzado
320	      //    Inclui 'OVER' se gasto > teto (>100%)
321	      const thresholds = [...(limit.alert_thresholds ?? [80, 90, 100])].sort((a, b) => a - b);
322	
323	      let highestCrossed: number | 'OVER' | null = null;
324	
325	      if (percent > 100) {
326	        highestCrossed = 'OVER';
327	      } else {
328	        for (const t of thresholds) {
329	          if (percent >= t) {
330	            highestCrossed = t;
331	          }
332	        }
333	      }
334	
335	      if (highestCrossed === null) return; // Nenhum threshold cruzado
336	
337	      // 4. Construir a chave de idempotência
338	      const periodKey = yyyymm(now);
339	      const thresholdKey = highestCrossed === 'OVER' ? 'OVER' : String(highestCrossed);
340	      const alertLink = `/company/financeiro?alert=${companyId}:${periodKey}:${thresholdKey}`;
341	
342	      // 5. Resolver o owner da empresa (user_id para a notificação)
343	      //    Usa o financial_contact_email se disponível, mas notificação in-app vai pro owner.
344	      const { data: companyRow, error: companyErr } = await supabase
345	        .from('companies')
346	        .select('owner_id')
347	        .eq('id', companyId)
348	        .maybeSingle();
349	
350	      if (companyErr || !companyRow) {
351	        logError('spendLimit.evaluateSpendAlert.company', companyErr ?? new Error('company not found'));
352	        return;
353	      }
354	      const ownerId = companyRow.owner_id as string;
355	
356	      // 6. Verificar idempotência: já existe alerta com este link?
357	      //    notifications_user_id_idx cobre user_id (sem full-scan).
358	      const { data: existing, error: checkErr } = await supabase
359	        .from('notifications')
360	        .select('id')
361	        .eq('user_id', ownerId)
362	        .eq('link', alertLink)
363	        .limit(1)
364	        .maybeSingle();
365	
366	      if (checkErr) {
367	        logError('spendLimit.evaluateSpendAlert.check', checkErr);
368	        return;
369	      }
370	      if (existing) return; // Alerta já enviado → idempotência
371	
372	      // 7. Compor mensagem do alerta
373	      const percentFormatted = Math.round(percent);
374	      const amountFormatted = totalAmount.toLocaleString('pt-BR', {
375	        style: 'currency',
376	        currency: 'BRL',
377	      });
378	      const limitFormatted = limit.amount.toLocaleString('pt-BR', {
379	        style: 'currency',
380	        currency: 'BRL',
381	      });
382	
383	      let title: string;
384	      let message: string;
385	
386	      if (highestCrossed === 'OVER') {
387	        title = 'Teto de gasto ultrapassado';
388	        message =
389	          `Gasto mensal de ${amountFormatted} ultrapassou o teto de ${limitFormatted} ` +
390	          `(${percentFormatted}%). As contratações continuam funcionando normalmente.`;
391	      } else {
392	        title = `Alerta: ${highestCrossed}% do teto de gasto atingido`;
393	        message =
394	          `Gasto mensal de ${amountFormatted} atingiu ${percentFormatted}% do teto de ` +
395	          `${limitFormatted}. As contratações continuam funcionando normalmente.`;
396	      }
397	
398	      // 8. Inserir notificação in-app
399	      const { error: insertErr } = await supabase.from('notifications').insert({
400	        user_id: ownerId,
401	        type: 'payment',
402	        title,
403	        message,
404	        link: alertLink,
405	      });
406	
407	      if (insertErr) {
408	        logError('spendLimit.evaluateSpendAlert.insert', insertErr);
409	        // Best-effort — não propaga o erro para não quebrar o pagamento
410	      }
411	    } catch (err) {
412	      // NUNCA propaga — alerta é best-effort (spec: "Alerta NUNCA bloqueia")
413	      logError('spendLimit.evaluateSpendAlert', err);
414	    }
415	  },
416	};
